/**
 * QuizLens AI - Popup Script
 * Handles configuration UI and testing connection
 */

import { DEFAULT_SETTINGS, PROVIDER_MODELS } from '../shared/constants';
import { ExtensionSettings, ProviderType } from '../shared/types';

document.addEventListener('DOMContentLoaded', () => {
  const enabledToggle = document.getElementById('enabledToggle') as HTMLInputElement;
  const providerSelect = document.getElementById('providerSelect') as HTMLSelectElement;
  const modelSelect = document.getElementById('modelSelect') as HTMLSelectElement;
  const apiKeyInput = document.getElementById('apiKeyInput') as HTMLInputElement;
  const toggleApiKeyVisBtn = document.getElementById('toggleApiKeyVis') as HTMLButtonElement;
  const autoCopyToggle = document.getElementById('autoCopyToggle') as HTMLInputElement;
  const testBtn = document.getElementById('testBtn') as HTMLButtonElement;
  const saveBtn = document.getElementById('saveBtn') as HTMLButtonElement;
  const statusBadge = document.getElementById('statusBadge') as HTMLDivElement;
  const feedbackMsg = document.getElementById('feedbackMsg') as HTMLDivElement;
  const keyHint = document.getElementById('keyHint') as HTMLSpanElement;

  let currentSettings: ExtensionSettings = { ...DEFAULT_SETTINGS };
  let currentActiveProvider: ProviderType = 'gemini';

  // Update Model dropdown based on Provider
  function updateModelOptions(provider: ProviderType, selectedModel?: string) {
    const models = PROVIDER_MODELS[provider] || [];
    modelSelect.innerHTML = '';
    models.forEach((m) => {
      const opt = document.createElement('option');
      opt.value = m;
      opt.textContent = m;
      if (m === selectedModel) {
        opt.selected = true;
      }
      modelSelect.appendChild(opt);
    });
  }

  // Update API key field placeholder, hint & value based on provider
  function syncApiKeyField(provider: ProviderType) {
    if (provider === 'gemini') {
      apiKeyInput.value = currentSettings.geminiApiKey || '';
      apiKeyInput.placeholder = 'AIzaSy...';
      keyHint.innerHTML = 'Lấy API Key miễn phí tại: <a href="https://aistudio.google.com/app/apikey" target="_blank" style="color: #2563EB; font-weight: 600;">Google AI Studio</a>';
    } else if (provider === 'groq') {
      apiKeyInput.value = currentSettings.groqApiKey || '';
      apiKeyInput.placeholder = 'gsk_...';
      keyHint.innerHTML = 'Lấy API Key miễn phí tại: <a href="https://console.groq.com/keys" target="_blank" style="color: #2563EB; font-weight: 600;">Groq Console</a>';
    } else if (provider === 'openai') {
      apiKeyInput.value = currentSettings.openaiApiKey || '';
      apiKeyInput.placeholder = 'sk-proj-... hoặc sk-...';
      keyHint.innerHTML = 'Lấy API Key tại: <a href="https://platform.openai.com/api-keys" target="_blank" style="color: #2563EB; font-weight: 600;">OpenAI Platform</a>';
    } else if (provider === 'deepseek') {
      apiKeyInput.value = currentSettings.deepseekApiKey || '';
      apiKeyInput.placeholder = 'sk-...';
      keyHint.innerHTML = 'Lấy API Key tại: <a href="https://platform.deepseek.com/api_keys" target="_blank" style="color: #2563EB; font-weight: 600;">DeepSeek Platform</a>';
    } else if (provider === 'openrouter') {
      apiKeyInput.value = currentSettings.openrouterApiKey || '';
      apiKeyInput.placeholder = 'sk-or-...';
      keyHint.innerHTML = 'Lấy API Key miễn phí tại: <a href="https://openrouter.ai/keys" target="_blank" style="color: #2563EB; font-weight: 600;">OpenRouter Keys</a>';
    }

    updateStatusBadge();
  }

  function updateStatusBadge() {
    const key = apiKeyInput.value.trim();
    if (key.length > 5) {
      statusBadge.textContent = 'Key sẵn sàng';
      statusBadge.className = 'status-badge connected';
    } else {
      statusBadge.textContent = 'Backend Online';
      statusBadge.className = 'status-badge connected';
    }
  }

  // Check Backend status on load
  chrome.runtime.sendMessage({ type: 'TEST_CONNECTION' }, (res) => {
    if (res?.success) {
      statusBadge.textContent = apiKeyInput.value.trim().length > 5 ? 'Key sẵn sàng' : 'Backend Online';
      statusBadge.className = 'status-badge connected';
    } else {
      statusBadge.textContent = 'Backend Offline';
      statusBadge.className = 'status-badge error';
    }
  });

  // Load settings from Service Worker
  chrome.runtime.sendMessage({ type: 'GET_SETTINGS' }, (response) => {
    if (response?.success && response.data) {
      currentSettings = { ...DEFAULT_SETTINGS, ...response.data };
      currentActiveProvider = currentSettings.activeProvider || 'gemini';

      enabledToggle.checked = currentSettings.enabled;
      providerSelect.value = currentActiveProvider;
      autoCopyToggle.checked = currentSettings.autoCopy;

      if (currentSettings.groqModel && currentSettings.groqModel.includes('mixtral')) {
        currentSettings.groqModel = 'llama-3.3-70b-versatile';
      }

      const activeModel =
        currentActiveProvider === 'gemini'
          ? currentSettings.geminiModel
          : currentActiveProvider === 'groq'
          ? currentSettings.groqModel
          : currentActiveProvider === 'openai'
          ? currentSettings.openaiModel
          : currentActiveProvider === 'deepseek'
          ? currentSettings.deepseekModel
          : currentSettings.openrouterModel;

      updateModelOptions(currentActiveProvider, activeModel);
      syncApiKeyField(currentActiveProvider);
    }
  });

  // Handle Provider Change
  providerSelect.addEventListener('change', () => {
    // Preserve current input into previous provider before switching
    const currentVal = apiKeyInput.value.trim();
    if (currentActiveProvider === 'gemini') currentSettings.geminiApiKey = currentVal;
    else if (currentActiveProvider === 'groq') currentSettings.groqApiKey = currentVal;
    else if (currentActiveProvider === 'openai') currentSettings.openaiApiKey = currentVal;
    else if (currentActiveProvider === 'deepseek') currentSettings.deepseekApiKey = currentVal;
    else if (currentActiveProvider === 'openrouter') currentSettings.openrouterApiKey = currentVal;

    const newProvider = providerSelect.value as ProviderType;
    currentActiveProvider = newProvider;
    currentSettings.activeProvider = newProvider;

    const targetModel =
      newProvider === 'gemini'
        ? currentSettings.geminiModel
        : newProvider === 'groq'
        ? currentSettings.groqModel
        : newProvider === 'openai'
        ? currentSettings.openaiModel
        : newProvider === 'deepseek'
        ? currentSettings.deepseekModel
        : currentSettings.openrouterModel;

    updateModelOptions(newProvider, targetModel);
    syncApiKeyField(newProvider);
  });

  apiKeyInput.addEventListener('input', () => {
    const val = apiKeyInput.value.trim();
    if (currentActiveProvider === 'gemini') currentSettings.geminiApiKey = val;
    else if (currentActiveProvider === 'groq') currentSettings.groqApiKey = val;
    else if (currentActiveProvider === 'openai') currentSettings.openaiApiKey = val;
    else if (currentActiveProvider === 'deepseek') currentSettings.deepseekApiKey = val;
    else if (currentActiveProvider === 'openrouter') currentSettings.openrouterApiKey = val;

    updateStatusBadge();
  });

  // Toggle API key visibility
  let isKeyVisible = false;
  toggleApiKeyVisBtn.addEventListener('click', () => {
    isKeyVisible = !isKeyVisible;
    apiKeyInput.type = isKeyVisible ? 'text' : 'password';
    toggleApiKeyVisBtn.textContent = isKeyVisible ? 'Ẩn' : 'Hiện';
  });

  // Test Connection
  testBtn.addEventListener('click', () => {
    testBtn.disabled = true;
    testBtn.textContent = 'Đang kiểm tra...';
    statusBadge.textContent = 'Đang kết nối...';
    statusBadge.className = 'status-badge';

    const provider = providerSelect.value as ProviderType;
    const model = modelSelect.value;
    const key = apiKeyInput.value.trim();

    chrome.runtime.sendMessage(
      {
        type: 'TEST_CONNECTION',
        payload: { provider, model, apiKey: key, isExplicitTest: true }
      },
      (res) => {
        testBtn.disabled = false;
        testBtn.textContent = 'Kiểm tra kết nối';
        if (res?.success) {
          statusBadge.textContent = 'Đã kết nối AI';
          statusBadge.className = 'status-badge connected';
          showFeedback(res.data?.message || 'Kết nối thành công!', 'success');
        } else {
          statusBadge.textContent = 'Lỗi kết nối';
          statusBadge.className = 'status-badge error';
          showFeedback(`Lỗi: ${res?.error || 'Không kết nối được'}`, 'error');
        }
      }
    );
  });

  // Save Settings
  saveBtn.addEventListener('click', () => {
    const activeProvider = providerSelect.value as ProviderType;
    const selectedModel = modelSelect.value;
    const apiKey = apiKeyInput.value.trim();

    const updated: Partial<ExtensionSettings> = {
      enabled: enabledToggle.checked,
      activeProvider,
      autoCopy: autoCopyToggle.checked
    };

    if (activeProvider === 'gemini') {
      updated.geminiModel = selectedModel;
      updated.geminiApiKey = apiKey;
      currentSettings.geminiApiKey = apiKey;
      currentSettings.geminiModel = selectedModel;
    } else if (activeProvider === 'groq') {
      updated.groqModel = selectedModel;
      updated.groqApiKey = apiKey;
      currentSettings.groqApiKey = apiKey;
      currentSettings.groqModel = selectedModel;
    } else if (activeProvider === 'openai') {
      updated.openaiModel = selectedModel;
      updated.openaiApiKey = apiKey;
      currentSettings.openaiApiKey = apiKey;
      currentSettings.openaiModel = selectedModel;
    } else if (activeProvider === 'deepseek') {
      updated.deepseekModel = selectedModel;
      updated.deepseekApiKey = apiKey;
      currentSettings.deepseekApiKey = apiKey;
      currentSettings.deepseekModel = selectedModel;
    } else if (activeProvider === 'openrouter') {
      updated.openrouterModel = selectedModel;
      updated.openrouterApiKey = apiKey;
      currentSettings.openrouterApiKey = apiKey;
      currentSettings.openrouterModel = selectedModel;
    }

    chrome.runtime.sendMessage({ type: 'SAVE_SETTINGS', payload: updated }, (res) => {
      if (res?.success) {
        currentSettings = { ...currentSettings, ...updated };
        updateStatusBadge();
        const providerNames: Record<ProviderType, string> = {
          gemini: 'Google Gemini',
          groq: 'Groq Cloud',
          openai: 'OpenAI (ChatGPT)',
          deepseek: 'DeepSeek AI',
          openrouter: 'OpenRouter'
        };
        const providerName = providerNames[activeProvider] || activeProvider;
        showFeedback(`Đã lưu cấu hình: ${providerName} (${selectedModel})!`, 'success');
      } else {
        showFeedback('Lỗi khi lưu cấu hình.', 'error');
      }
    });
  });

  function showFeedback(text: string, type: 'success' | 'error') {
    feedbackMsg.textContent = text;
    feedbackMsg.className = `feedback-msg ${type}`;
    if (type === 'success') {
      setTimeout(() => {
        if (feedbackMsg.textContent === text) {
          feedbackMsg.textContent = '';
        }
      }, 3500);
    }
  }
});
